using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
namespace Ingestion {
    public static class Utilities {
        public static string Json(object o){return new JavaScriptSerializer{MaxJsonLength=int.MaxValue}.Serialize(o);}
        public static T ReadJson<T>(string path){return new JavaScriptSerializer{MaxJsonLength=int.MaxValue}.Deserialize<T>(File.ReadAllText(path,Encoding.UTF8));}
        public static string Now(){return DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture);}
        public static string Hash(byte[] bytes){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
        public static string FileHash(string path){using(var s=File.OpenRead(path))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
        public static void DurableWrite(string path,string text){string full=Path.GetFullPath(path);Directory.CreateDirectory(Path.GetDirectoryName(full));using(var f=new FileStream(full,FileMode.Create,FileAccess.Write,FileShare.Read)){var b=new UTF8Encoding(false).GetBytes(text);f.Write(b,0,b.Length);f.Flush(true);}}
        public static string CanonicalHash(CanonicalRecord r){return Hash(Encoding.UTF8.GetBytes(Json(new[]{r.record_id,r.dataset,r.source_category,r.field,r.unit,r.value,r.source_locator})));}
        public static CanonicalRecord FromRow(Dictionary<string,string> d){return new CanonicalRecord{record_id=d["record_id"],dataset=d["dataset"],source_category=d["source_category"],field=d["field"],unit=d["unit"],value=d["value"],source_locator=d["source_locator"]};}
    }
    public static class Validator {
        public static readonly string[] Fields={"record_id","dataset","source_category","field","unit","value","source_locator"};
        public static List<CanonicalRecord> Validate(IEnumerable<CanonicalRecord> input,string locale){var result=new List<CanonicalRecord>();var ids=new HashSet<string>();CultureInfo culture=(locale=="invariant"||locale=="dot"||String.IsNullOrEmpty(locale))?CultureInfo.InvariantCulture:CultureInfo.GetCultureInfo(locale=="comma"?"de-DE":locale);foreach(var r in input){foreach(var f in Fields){var info=typeof(CanonicalRecord).GetField(f);string text=Convert.ToString(info.GetValue(r));if(f!="unit"&&String.IsNullOrWhiteSpace(text))throw new InvalidDataException("MISSING_REQUIRED:"+f);if(text.Any(ch=>char.IsControl(ch)))throw new InvalidDataException("CONTROL_CHARACTER:"+f);info.SetValue(r,text.Trim().Normalize(NormalizationForm.FormC));}if(!new[]{"client_real","public_real","public_synthetic","derived","controlled_injection","unverified"}.Contains(r.source_category))throw new InvalidDataException("UNKNOWN_SOURCE_CATEGORY:"+r.source_category);decimal v;if(!Decimal.TryParse(r.value,NumberStyles.Float,culture,out v))throw new InvalidDataException("INVALID_DECIMAL:"+r.value);r.value=v.ToString("G29",CultureInfo.InvariantCulture);if(!ids.Add(r.record_id))throw new InvalidDataException("DUPLICATE_ID_IN_INPUT:"+r.record_id);result.Add(r);}if(result.Count==0)throw new InvalidDataException("NO_RECORDS");return result;}
    }
    public sealed class Options {
        public string Manifest,Database,Output,Plugins,Fault="",Signal="",Python="",PdfBridge="";public int Concurrency=1;
        public static Options Parse(string[] args){if(args.Length==0||args[0]!="ingest")throw new ArgumentException("ingest --input manifest.json --db records.sqlite --output dir [--plugins dir] [--concurrency N] [--python executable] [--pdf-bridge script] [--fault transaction_abort|hold_before_commit|hold_after_commit] [--signal ready.json]");var o=new Options();for(int i=1;i<args.Length;i+=2){if(i+1>=args.Length)throw new ArgumentException("Missing option value");string k=args[i],v=args[i+1];switch(k){case "--input":o.Manifest=Path.GetFullPath(v);break;case "--db":o.Database=Path.GetFullPath(v);break;case "--output":o.Output=Path.GetFullPath(v);break;case "--plugins":o.Plugins=Path.GetFullPath(v);break;case "--concurrency":o.Concurrency=Int32.Parse(v);break;case "--fault":o.Fault=v;break;case "--signal":o.Signal=Path.GetFullPath(v);break;case "--python":o.Python=v;break;case "--pdf-bridge":o.PdfBridge=Path.GetFullPath(v);break;default:throw new ArgumentException("Unknown option:"+k);}}if(o.Manifest==null||o.Database==null||o.Output==null||o.Concurrency<1)throw new ArgumentException("Required input/db/output or valid concurrency missing");if(o.Plugins==null)o.Plugins=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"plugins");if(o.Python=="")o.Python=Environment.GetEnvironmentVariable("PIPELINE_PYTHON")??"python";if(o.PdfBridge=="")o.PdfBridge=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","scripts","pdf_bridge.py"));return o;}
    }
    public sealed class DurableLog : IDisposable {
        FileStream stream;object gate=new object();public DurableLog(string path){stream=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.Read);}
        public void Add(object data){byte[] b=new UTF8Encoding(false).GetBytes(Utilities.Json(data)+"\n");lock(gate){stream.Write(b,0,b.Length);stream.Flush(true);}}
        public void Dispose(){stream.Dispose();}
    }
    public static class Store {
        public const string Schema="CREATE TABLE IF NOT EXISTS records(record_id TEXT PRIMARY KEY,dataset TEXT NOT NULL,source_category TEXT NOT NULL,field TEXT NOT NULL,unit TEXT NOT NULL,value TEXT NOT NULL,source_locator TEXT NOT NULL,canonical_hash TEXT NOT NULL); CREATE TABLE IF NOT EXISTS file_audit(file_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,input_path TEXT NOT NULL,input_sha256 TEXT NOT NULL,plugin_name TEXT NOT NULL,plugin_version TEXT NOT NULL,plugin_sha256 TEXT NOT NULL,status TEXT NOT NULL,started_utc TEXT NOT NULL,completed_utc TEXT,elapsed_ms REAL NOT NULL DEFAULT 0,expected_rows INTEGER NOT NULL DEFAULT 0,inserted_rows INTEGER NOT NULL DEFAULT 0,idempotent_rows INTEGER NOT NULL DEFAULT 0,error_code TEXT NOT NULL DEFAULT '',quarantine_path TEXT NOT NULL DEFAULT ''); CREATE TABLE IF NOT EXISTS record_sources(file_id TEXT NOT NULL REFERENCES file_audit(file_id),record_id TEXT NOT NULL REFERENCES records(record_id),canonical_hash TEXT NOT NULL,source_locator TEXT NOT NULL,PRIMARY KEY(file_id,record_id));";
        public static void Retry(Action work,Action<int,Exception> report){for(int attempt=1;;attempt++)try{work();return;}catch(SqliteException e){if(!e.Transient||attempt>=12)throw;if(report!=null)report(attempt,e);Thread.Sleep(Math.Min(1000,20*(1<<(attempt-1))));}}
        public static void Init(string path,Action<int,Exception> report=null){Directory.CreateDirectory(Path.GetDirectoryName(path));Retry(()=>{using(var d=new NativeSqlite(path)){d.Exec("PRAGMA journal_mode=WAL;");d.Exec(Schema);}},report);}
        public static int Reconcile(string path,DurableLog log){int n=0;using(var d=new NativeSqlite(path)){var pending=d.Query("SELECT * FROM file_audit WHERE status IN ('started','committed');");foreach(var audit in pending){string id=audit["file_id"],status;var sources=d.Query("SELECT r.*,s.canonical_hash AS source_hash FROM record_sources s JOIN records r ON r.record_id=s.record_id WHERE s.file_id="+NativeSqlite.Q(id)+";");if(audit["status"]=="started"&&sources.Count==0)status="interrupted_uncommitted";else if(audit["status"]=="committed"&&sources.Count==Int32.Parse(audit["expected_rows"])&&sources.All(r=>Utilities.CanonicalHash(Utilities.FromRow(r))==r["canonical_hash"]&&r["source_hash"]==r["canonical_hash"]))status="verified_reconciled";else status="reconciliation_failed";d.Exec("UPDATE file_audit SET status="+NativeSqlite.Q(status)+",completed_utc="+NativeSqlite.Q(Utilities.Now())+" WHERE file_id="+NativeSqlite.Q(id)+";");log.Add(new{event_type="reconcile",file_id=id,prior_status=audit["status"],status=status,utc=Utilities.Now(),records=sources.Count});n++;}}return n;}
        public static void Intent(string path,string id,string run,string input,string hash,string plugin,string version,string pluginHash,string began,Action<int,Exception> report=null){Retry(()=>{using(var d=new NativeSqlite(path))d.Exec("INSERT INTO file_audit(file_id,run_id,input_path,input_sha256,plugin_name,plugin_version,plugin_sha256,status,started_utc) VALUES("+String.Join(",",new[]{id,run,input,hash,plugin,version,pluginHash,"started",began}.Select(NativeSqlite.Q))+");");},report);}
        public static string Values(CanonicalRecord r){return String.Join(",",new[]{r.record_id,r.dataset,r.source_category,r.field,r.unit,r.value,r.source_locator,Utilities.CanonicalHash(r)}.Select(NativeSqlite.Q));}
        public static void Terminal(string path,string id,string status,string ended,double elapsed,string error,string quarantine){Retry(()=>{using(var d=new NativeSqlite(path))d.Exec("UPDATE file_audit SET status="+NativeSqlite.Q(status)+",completed_utc="+NativeSqlite.Q(ended)+",elapsed_ms="+elapsed.ToString("R",CultureInfo.InvariantCulture)+",error_code="+NativeSqlite.Q(error)+",quarantine_path="+NativeSqlite.Q(quarantine)+" WHERE file_id="+NativeSqlite.Q(id)+";");},null);}
    }
    public sealed class FileResult {public string file_id,input_path,input_sha256,plugin_name,plugin_version,plugin_sha256,status,error_code,started_utc,ended_utc,quarantine_path;public int nrows,inserted_rows,idempotent_rows,retries;public double latency_ms;public bool audit_db_complete;}
    public static class Engine {
        static void Hook(Options o,string stage,string run,string id,int rows){if(o.Fault!=stage)return;if(String.IsNullOrEmpty(o.Signal))throw new ArgumentException("Fault hold requires --signal");Utilities.DurableWrite(o.Signal,Utilities.Json(new{stage=stage,run_id=run,file_id=id,pid=Process.GetCurrentProcess().Id,expected_rows=rows,utc=Utilities.Now()}));Thread.Sleep(Timeout.Infinite);}
        static FileResult File(Options o,InputFile input,IFormatPlugin[] plugins,string run,int index,DurableLog log){string full=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(o.Manifest),input.path));var result=new FileResult{file_id=run+"-f"+index.ToString("D5"),input_path=full,started_utc=Utilities.Now(),status="failed",error_code="",quarantine_path=""};result.input_path=Path.IsPathRooted(input.path)?Path.GetFileName(input.path):input.path.Replace('\\','/');var watch=Stopwatch.StartNew();bool intent=false,parsing=false;log.Add(new{event_type="intent",run_id=run,file_id=result.file_id,input_path=result.input_path,utc=result.started_utc});try{result.input_sha256=Utilities.FileHash(full);var chosen=plugins.Where(p=>p.CanHandle(full)).ToArray();if(chosen.Length!=1)throw new InvalidDataException(chosen.Length==0?"NO_PLUGIN":"AMBIGUOUS_PLUGIN");var plugin=chosen[0];result.plugin_name=plugin.Name;result.plugin_version=plugin.Version;result.plugin_sha256=Utilities.FileHash(plugin.GetType().Assembly.Location);Store.Intent(o.Database,result.file_id,run,result.input_path,result.input_sha256,result.plugin_name,result.plugin_version,result.plugin_sha256,result.started_utc,(a,e)=>{result.retries++;log.Add(new{event_type="retry",stage="intent",file_id=result.file_id,attempt=a,error_code=e.Message,utc=Utilities.Now()});});intent=true;parsing=true;var rows=Validator.Validate(plugin.Parse(new ParseContext{Input=input,FullPath=full,PythonExecutable=o.Python,PdfBridgePath=o.PdfBridge}),input.decimal_locale);parsing=false;result.nrows=rows.Count;
            Store.Retry(()=>{using(var db=new NativeSqlite(o.Database)){bool committed=false;db.Exec("BEGIN IMMEDIATE;");try{int inserted=0,idempotent=0;foreach(var record in rows){string hash=Utilities.CanonicalHash(record),existing=db.Scalar("SELECT canonical_hash FROM records WHERE record_id="+NativeSqlite.Q(record.record_id)+";");if(existing==null){db.Exec("INSERT INTO records VALUES("+Store.Values(record)+");");inserted++;}else{if(existing!=hash)throw new InvalidDataException("CONFLICTING_RECORD:"+record.record_id);idempotent++;}db.Exec("INSERT INTO record_sources VALUES("+NativeSqlite.Q(result.file_id)+","+NativeSqlite.Q(record.record_id)+","+NativeSqlite.Q(hash)+","+NativeSqlite.Q(record.source_locator)+");");if(o.Fault=="transaction_abort")throw new IOException("INJECTED_TRANSACTION_ABORT_AFTER_INSERT");}db.Exec("UPDATE file_audit SET status='committed',expected_rows="+rows.Count+",inserted_rows="+inserted+",idempotent_rows="+idempotent+" WHERE file_id="+NativeSqlite.Q(result.file_id)+";");Hook(o,"hold_before_commit",run,result.file_id,rows.Count);db.Exec("COMMIT;");committed=true;result.inserted_rows=inserted;result.idempotent_rows=idempotent;Hook(o,"hold_after_commit",run,result.file_id,rows.Count);var actual=db.Query("SELECT r.* FROM records r JOIN record_sources s ON s.record_id=r.record_id WHERE s.file_id="+NativeSqlite.Q(result.file_id)+";");var expected=rows.ToDictionary(r=>r.record_id,Utilities.CanonicalHash);if(actual.Count!=rows.Count||actual.Any(r=>!expected.ContainsKey(r["record_id"])||Utilities.CanonicalHash(Utilities.FromRow(r))!=expected[r["record_id"]]))throw new InvalidDataException("READBACK_MISMATCH");}finally{if(!committed)try{db.Exec("ROLLBACK;");}catch{}}}},(attempt,e)=>{result.retries++;log.Add(new{event_type="retry",stage="transaction",file_id=result.file_id,attempt=attempt,error_code=e.Message,utc=Utilities.Now()});});result.status="verified";result.ended_utc=Utilities.Now();Store.Terminal(o.Database,result.file_id,result.status,result.ended_utc,watch.Elapsed.TotalMilliseconds,"","");result.audit_db_complete=true;
        }catch(Exception e){result.error_code=e.GetType().Name+":"+e.Message.Replace(full,"[INPUT_FILE]").Replace(o.Database,"[DATABASE]").Replace(o.Output,"[OUTPUT_DIRECTORY]");result.status=(parsing||e is InvalidDataException||e is FormatException||e is ArgumentException)?"quarantined":"failed";if(result.status=="quarantined"){Directory.CreateDirectory(Path.Combine(o.Output,"quarantine"));result.quarantine_path="quarantine/"+result.file_id+Path.GetExtension(full);try{System.IO.File.Copy(full,Path.Combine(o.Output,result.quarantine_path),false);}catch(Exception copy){result.error_code+=";QUARANTINE_COPY_FAILED:"+copy.Message;}}result.ended_utc=Utilities.Now();try{if(!intent){Store.Intent(o.Database,result.file_id,run,result.input_path,result.input_sha256??"UNAVAILABLE",result.plugin_name??"UNAVAILABLE",result.plugin_version??"UNAVAILABLE",result.plugin_sha256??"UNAVAILABLE",result.started_utc);intent=true;}Store.Terminal(o.Database,result.file_id,result.status,result.ended_utc,watch.Elapsed.TotalMilliseconds,result.error_code,result.quarantine_path);result.audit_db_complete=true;}catch(Exception audit){result.error_code+=";AUDIT_DB_WRITE_FAILED:"+audit.Message;}}
            result.latency_ms=watch.Elapsed.TotalMilliseconds;result.ended_utc=Utilities.Now();log.Add(new{event_type="terminal",run_id=run,result=result});return result;}
        static double Percentile(double[] values,double p){if(values.Length==0)return 0;double n=(values.Length-1)*p;int a=(int)n,b=(int)Math.Ceiling(n);return values[a]+(values[b]-values[a])*(n-a);}
        public static int Run(Options o,IFormatPlugin[] plugins,string mode,Stopwatch total,double discoveryMs,double initialCpuMs){Directory.CreateDirectory(o.Output);string run=Guid.NewGuid().ToString("N");using(var log=new DurableLog(Path.Combine(o.Output,"events.jsonl"))){Store.Init(o.Database,(a,e)=>log.Add(new{event_type="retry",stage="initialization",attempt=a,error_code=e.Message,utc=Utilities.Now()}));int reconciled=Store.Reconcile(o.Database,log);var manifest=Utilities.ReadJson<InputManifest>(o.Manifest);if(manifest.files==null)throw new InvalidDataException("Manifest.files missing");var results=new FileResult[manifest.files.Count];Parallel.For(0,manifest.files.Count,new ParallelOptions{MaxDegreeOfParallelism=o.Concurrency},i=>{results[i]=File(o,manifest.files[i],plugins,run,i,log);});int count,complete;using(var db=new NativeSqlite(o.Database)){count=Int32.Parse(db.Scalar("SELECT count(*) FROM records;"));complete=Int32.Parse(db.Scalar("SELECT count(*) FROM records r WHERE EXISTS(SELECT 1 FROM record_sources s JOIN file_audit a ON a.file_id=s.file_id WHERE s.record_id=r.record_id AND a.input_sha256<>'' AND a.plugin_version<>'' AND a.input_path<>'' AND a.plugin_sha256<>'' AND s.source_locator<>'');"));}var proc=Process.GetCurrentProcess();proc.Refresh();double duration=total.Elapsed.TotalMilliseconds,cpu=proc.TotalProcessorTime.TotalMilliseconds-initialCpuMs;var lat=results.Select(r=>r.latency_ms).OrderBy(x=>x).ToArray();var summary=new{schema_version=1,manifest_sha256=Utilities.FileHash(o.Manifest),run_id=run,mode=mode,pid=proc.Id,utc=Utilities.Now(),duration_ms=duration,discovery_ms=discoveryMs,total_cpu_ms=cpu,cpu_percent_normalized=cpu/duration/Environment.ProcessorCount*100,logical_processors=Environment.ProcessorCount,peak_working_set_bytes=proc.PeakWorkingSet64,working_set_bytes=proc.WorkingSet64,concurrency=o.Concurrency,files_attempted=results.Length,files_verified=results.Count(r=>r.status=="verified"),files_quarantined=results.Count(r=>r.status=="quarantined"),files_failed=results.Count(r=>r.status=="failed"),records_submitted=results.Sum(r=>r.nrows),records_inserted=results.Sum(r=>r.inserted_rows),records_idempotent=results.Sum(r=>r.idempotent_rows),record_count=count,provenance_complete_records=complete,provenance_completeness=count==0?1:(double)complete/count,audit_db_complete_files=results.Count(r=>r.audit_db_complete),reconciled_audits=reconciled,p50_file_latency_ms=Percentile(lat,.5),p95_file_latency_ms=Percentile(lat,.95),p99_file_latency_ms=Percentile(lat,.99),file_latencies_ms=lat,throughput_records_per_second=results.Where(r=>r.status=="verified").Sum(r=>r.nrows)/(duration/1000),plugins=plugins.Select(p=>new{name=p.Name,version=p.Version,assembly_sha256=Utilities.FileHash(p.GetType().Assembly.Location)}).ToArray(),sqlite_version=NativeSqlite.Version,pragmas="journal_mode=WAL;synchronous=FULL;busy_timeout=0;foreign_keys=ON",retry_policy="SQLite BUSY/LOCKED only; max12 attempts, exponential20ms capped1000ms, 6260ms total configured backoff",results=results};Utilities.DurableWrite(Path.Combine(o.Output,"summary.json"),Utilities.Json(summary));return results.Any(r=>r.status!="verified")?2:0;}}
    }
}
